def solve_small_n(n):
    def backtrack(index, current_sum, current_weighted_sum, current_a):
        if index == n + 1:
            if current_sum == n + 1 and current_weighted_sum == n + 1:
                b = [0] * (n + 1)
                for x in current_a:
                    if x <= n:
                        b[x] += 1
                    else:
                        return # a_k cannot be > n
                if sum(b) == n + 1 and sum(i * b[i] for i in range(n + 1)) == n + 1:
                    a_from_b = [0] * (n + 1)
                    for x in b:
                        if x <= n:
                            a_from_b[x] += 1
                    if current_a == a_from_b:
                        yield list(current_a)
            return

        for val in range(n + 2):
            if current_sum + val <= n + 1 and current_weighted_sum + index * val <= n + 1:
                current_a.append(val)
                yield from backtrack(index + 1, current_sum + val, current_weighted_sum + index * val, current_a)
                current_a.pop()

    return list(backtrack(0, 0, 0, []))

for n in range(1, 11):
    res = solve_small_n(n)
    print(f"n={n}: {res}")

