def solve_small(n):
    import itertools
    # Use a more efficient way to generate these sequences
    def generate_sequences(n, target_sum):
        if n == 1:
            yield (target_sum,)
            return
        for i in range(target_sum + 1):
            for rest in generate_sequences(n - 1, target_sum - i):
                yield (i,) + rest

    results = []
    for a in generate_sequences(n + 1, n + 1):
        b = count_sequence(a)
        c = count_sequence(b)
        if c == a:
            results.append(a)
    return results

