def find_good_sequences_ff(N):
    import itertools
    def generate_sequences(n, target_sum):
        if n == 1:
            yield (target_sum,)
            return
        for i in range(target_sum + 1):
            for rest in generate_sequences(n - 1, target_sum - i):
                yield (i,) + rest

    good_sequences = []
    for a in generate_sequences(N, N):
        b = count_sequence(a)
        c = count_sequence(b)
        if list(c) == list(a):
            good_sequences.append(a)
    return good_sequences

