import itertools

def find_good_sequences(n):
    results = []

    # a_k sequence: sum(a_k) = n+1, sum(k*a_k) = n+1, 0 <= a_k <= n
    # b_k sequence: sum(b_k) = n+1, sum(k*b_k) = n+1, 0 <= b_k <= n

    # Let's find all a_k such that sum a_k = n+1 and sum k a_k = n+1 and 0 <= a_k <= n
    # We can use recursion with memoization or just a simple search for small n.

    def search_a(k, current_sum, current_k_sum, current_a):
        if k == n + 1:
            if current_sum == n + 1 and current_k_sum == n + 1:
                # b_k is the count of a_i = k
                b = [0] * (n + 1)
                for val in current_a:
                    if val <= n:
                        b[val] += 1
                    else:
                        return # a_i must be <= n

                # Now check if b satisfies the conditions
                if sum(b) == n + 1 and sum(i * b[i] for i in range(n + 1)) == n + 1:
                    # a_k is the count of b_i = k
                    a_prime = [0] * (n + 1)
                    for val in b:
                        if val <= n:
                            a_prime[val] += 1
                        else:
                            # b_i must be <= n
                            return

                    if a_prime == current_a:
                        results.append((list(current_a), list(b)))
            return

        # The maximum value for a_k is n+1 - current_sum
        for val in range(n + 2):
            if current_sum + val <= n + 1 and current_k_sum + k * val <= n + 1:
                current_a.append(val)
                search_a(k + 1, current_sum + val, current_k_sum + k * val, current_a)
                current_a.pop()

    search_a(0, 0, 0, [])
    return results

